/**
 * 外部AIの提案をまとめて確かめて承認する（設計書6.87.18）。
 *
 * ここは「どれを束ねるか」と「確かめる画面に何を並べるか」だけを決める。
 * **反映そのものは、1件ずつの「反映する」と同じ道**（提案パネルの
 * `applyRecordUpdateById`）を通す——作者のデータの保護（`authorNotes`・
 * `autoGenerated: false`・`authorLocked`・6.18 の話数の扱い）はその道が
 * 守っているので、束ねる側で迂回しない。
 *
 * **出どころは画面の文言（`source`）ではなく、機械の印（`origin`）で見る。**
 * 文言で見分けると、言い回しを直した日に黙って効かなくなる。
 *
 * VS Code API に依存しない。
 */

export interface BulkApprovalCandidate {
  id: string;
  name: string;
  status: string;
  /** 出どころの印（`core/pendingUpdateFormat.ts` の `PendingUpdateSource`） */
  origin?: string;
  /** 画面に出している説明（出どころ・中身・理由） */
  source: string;
}

/** 外部AIの印 */
export const EXTERNAL_ORIGIN = "external";

/**
 * 束ねる対象：外部AIから来た、まだ判断していないもの。
 *
 * **失敗して残っているもの（`failed`）も入れる。** 手を付けたが片付いて
 * いない——1件ずつの「まとめて反映」と同じ数え方にそろえる。
 */
export function externalBulkTargets<T extends BulkApprovalCandidate>(
  items: readonly T[]
): T[] {
  return items.filter(
    (item) =>
      item.origin === EXTERNAL_ORIGIN &&
      (item.status === "pending" || item.status === "failed")
  );
}

/** 「外部AIの提案をまとめて確かめる」を出すか */
export function hasExternalPending(
  items: readonly BulkApprovalCandidate[]
): boolean {
  return externalBulkTargets(items).length > 0;
}

/** 確かめる画面に並べる件数の上限。多すぎるとモーダルが画面からはみ出す */
const MAX_LINES = 20;

/**
 * 確かめる画面の中身。**名前と中身（出どころ・理由）を1件ずつ並べる。**
 * 多いときは切るが、**残りの件数を必ず言う**（黙って隠さない）。
 */
export function bulkApprovalDetail(
  targets: readonly BulkApprovalCandidate[],
  max = MAX_LINES
): string {
  const lines = targets.slice(0, max).map((item) => `・${item.name}：${item.source}`);
  if (targets.length > max) lines.push(`ほか${targets.length - max}件`);
  return lines.join("\n");
}
